pages["/categories/detail/"]=()=>{let s=q.get("slug")||path.split("/").filter(Boolean).pop(),c=cats.find(x=>x[0]===s),list=products.filter(p=>p.category===s);return crumb("Catégories / "+(c?c[1]:s))+heading("CATEGORY / "+s.toUpperCase(),c?c[1]:"Univers sélectionné",c?c[2]:"Découvrez cette famille de produits CTRL-TECH.")+catalogNote+(list.length?productGrid(list):empty())};
