pages["/marques/detail/"]=()=>{let s=q.get("slug")||path.split("/").filter(Boolean).pop(),b=brands.find(x=>x.toLowerCase()===s.toLowerCase())||s,list=products.filter(p=>p.brand.toLowerCase()===String(b).toLowerCase());return crumb("Marques / "+b)+heading("BRAND / PROFILE",b,"Découvrez les références de cette marque dans la sélection de démonstration CTRL-TECH.")+catalogNote+(list.length?productGrid(list):empty("Aucune référence dans cette sélection","D’autres produits pourront être ajoutés après validation commerciale."))};
pages["/produit/detail/"]=()=>{let s=q.get("slug")||path.split("/").filter(Boolean).pop(),p=products.find(x=>x.id===s);if(!p)return crumb("Produit")+heading("PRODUCT / DETAILS","Produit introuvable.","Cette référence n’existe pas dans le catalogue.")+empty();return crumb("Catalogue / "+p.name)+'<div class="product-detail product-detail-live"><div class="product-image product-image-live"><img src="'+productImage(p)+'" alt="'+p.name+'"></div><div class="product-info-live"><small>'+p.brand.toUpperCase()+' / '+p.category.toUpperCase()+'</small><h1>'+p.name+'</h1><p>'+p.desc+'</p><div class="live-price">'+money(p.price)+'</div><div class="live-cdf">'+cdf(p.price)+' <span>conversion indicative</span></div><p class="rate-detail">'+rateLabel+' · 1 USD = 2 258,86 CDF</p><span class="demo-tag">'+(p.verifiedPrice?"PRIX PUBLIÉ PAR UN VENDEUR LOCAL":"PRIX ESTIMATIF · À CONFIRMER")+'</span><p class="availability-detail">'+p.availability+'</p><p class="source-detail">Repère local : '+p.sourceName+' · <a href="'+p.sourceUrl+'" target="_blank" rel="noopener">Consulter la source ↗</a></p><h3>Caractéristiques principales</h3><ul class="spec-list">'+p.specs.split(" · ").map(x=>'<li>'+x+'</li>').join("")+'</ul><a class="button" href="/contact/">Demander la disponibilité ↗</a></div></div><section class="related-products"><small>YOU MAY ALSO LIKE</small><h2>À découvrir également.</h2>'+productGrid(products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4))+'</section>'};
pages["/comparer/"]=()=>crumb("Comparateur")+heading("COMPARE","Comparer les produits.","Comparez jusqu’à trois produits à partir de leurs caractéristiques vérifiées.")+info("Comparateur en préparation","Il sera activé lorsque les fiches produits techniques auront été vérifiées et publiées.")+empty("Aucun produit à comparer","Les premières fiches produits ne sont pas encore disponibles.");
