pages["/a-propos/"]=()=>crumb("À propos")+heading("OUR APPROACH","La technologie, choisie avec précision.","CTRL-TECH est un espace dédié aux produits technologiques et à celles et ceux qui veulent en tirer le meilleur.")+'<article class="editorial"><h2>Choisir mieux.<br><em>Aller plus loin.</em></h2><p>Notre approche repose sur une sélection lisible, des informations transparentes et un accompagnement concret. Basée à Lubumbashi, CTRL-TECH développe une expérience de vente technologique guidée par les usages et la clarté.</p></article>';
pages["/contact/"]=()=>crumb("Contact")+heading("GET IN TOUCH","Parlons technologie.","Une question sur une gamme, une référence ou un service ?")+info("Lubumbashi, RDC","Les coordonnées, horaires et canaux de contact seront publiés après confirmation par CTRL-TECH.")+'<div class="content-card"><h2>Écrire à CTRL-TECH</h2>'+field("Nom complet")+field("Adresse e-mail","email")+field("Sujet")+field("Message")+'<button class="button" disabled>Envoyer — bientôt disponible</button></div>';
pages["/livraison/"]=()=>crumb("Livraison")+heading("DELIVERY INFORMATION","Livraison & retrait.","Les modalités seront communiquées de manière transparente.")+info("Informations en cours de validation","Zones desservies, délais, frais et options de retrait doivent être confirmés avant publication.");
pages["/garanties-retours/"]=()=>crumb("Garanties et retours")+heading("AFTER-SALES","Garanties & retours.","Consultez les conditions applicables aux produits achetés auprès de CTRL-TECH.")+info("Conditions à confirmer","Durées de garantie, exclusions, procédures de retour et remboursements seront publiés après validation.");
pages["/faq/"]=()=>crumb("FAQ")+heading("HELP CENTER","Questions fréquentes.","Les réponses essentielles concernant la boutique.")+'<div class="faq">'+[["Les produits sont-ils disponibles immédiatement ?","La disponibilité sera confirmée pour chaque référence."],["Comment connaître le prix ?","Les prix seront affichés après validation par la boutique."],["Livrez-vous en dehors de Lubumbashi ?","Les zones et conditions sont en cours de confirmation."],["Comment contacter CTRL-TECH ?","Les coordonnées officielles seront ajoutées après validation."]].map(x=>'<details><summary>'+x[0]+'</summary><p>'+x[1]+'</p></details>').join("")+'</div>';
pages["/conditions-generales/"]=()=>crumb("Conditions générales")+heading("LEGAL / TERMS","Conditions générales.","Conditions applicables à l’utilisation du site et aux ventes CTRL-TECH.")+'<article class="legal"><p>Cette page est une structure de travail à faire valider avant toute mise en vente.</p><h2>Informations commerciales</h2><p>Prix, disponibilités, délais, frais, garanties et modalités de paiement devront être communiqués avant confirmation d’une commande.</p><h2>Commandes et paiements</h2><p>Aucune commande ni aucun paiement n’est traité par cette interface de démonstration.</p></article>';
pages["/confidentialite/"]=()=>crumb("Confidentialité")+heading("LEGAL / PRIVACY","Confidentialité.","Comprendre les données susceptibles d’être traitées lors de l’utilisation du site.")+'<article class="legal"><p>La politique définitive devra identifier le responsable du traitement, les finalités, les bases légales, les durées de conservation, les destinataires et les droits des personnes.</p><p>Les formulaires de cette version ne transmettent pas de données à un serveur.</p></article>';
